export function playCoinflip(p) { const selected = p.payload?.side || 'heads'; const result = Math.random() < .5 ? 'heads' : 'tails'; const win = selected === result; const multiplier = 1.9; const winAmount = win ? Math.floor(p.betAmount * multiplier) : 0; return { game: 'coinflip', selected, result, win, multiplier, winAmount }; }
